using System;
using System.Linq;
using TMPro;
using UnityEngine;

namespace Verdant.Automation
{
    public sealed class ClassicManualBlock:MonoBehaviour
    {
        public TMP_Text text;public UnityEngine.UI.LayoutElement layout;float width=-1;string value;
        void LateUpdate(){if(text==null||layout==null)return;float next=text.rectTransform.rect.width;if(next<10||Math.Abs(next-width)<1&&text.text==value)return;width=next;value=text.text;layout.preferredHeight=Math.Max(70,text.GetPreferredValues(value,width,0).y+36);}
    }
    [Serializable] public sealed class ManualChapter
    {
        public string id,enTitle,zhTitle,en,zh,code;
        public ManualChapter(string id,string enTitle,string zhTitle,string en,string zh,string code=""){this.id=id;this.enTitle=enTitle;this.zhTitle=zhTitle;this.en=en;this.zh=zh;this.code=code;}
    }
    public sealed partial class ClassicController
    {
        string manualChapter="start",manualQuery="";
        void ManualBlock(string text,bool code=false)
        {
            var row=Surface(code?"Manual Code":"Manual Text",modalBody,Vector2.zero,Vector2.one,code?Dark:Paper);
            var layout=row.gameObject.AddComponent<UnityEngine.UI.LayoutElement>();layout.preferredHeight=120;
            var label=Label(text,row,new Vector2(.02f,0),new Vector2(.98f,1),code?17:19,code?Lime:Ink);label.enableAutoSizing=false;label.enableWordWrapping=true;label.richText=false;label.margin=new Vector4(0,18,0,18);
            var resize=row.gameObject.AddComponent<ClassicManualBlock>();resize.text=label;resize.layout=layout;
        }
        void BuildManual()
        {
            Paragraph(Tr("FIELD MANUAL / Learn, implement, measure","田野手册 / 理解、编写、测量"),60);
            var searchRow=Row(Tr("Search chapters","查找章节"),Tr("Search a crop, API, or symptom. Press Enter; clear to show all chapters.","输入作物、接口或问题后按回车；清空可显示全部章节。"),Tr("Clear","清空"),()=>{manualQuery="";Open("guide");});
            var search=MakeInput("Manual Search",searchRow,new Vector2(.02f,.06f),new Vector2(.65f,.35f),false);search.SetTextWithoutNotify(manualQuery);search.onEndEdit.AddListener(value=>{manualQuery=value.Trim();Open("guide");});
            var chapters=ClassicManual.Chapters.Where(c=>manualQuery==""||(c.enTitle+" "+c.zhTitle+" "+c.en+" "+c.zh+" "+c.code).IndexOf(manualQuery,StringComparison.OrdinalIgnoreCase)>=0||UnifiedManual.Matches(c.id,manualQuery)).ToArray();
            if(chapters.Length==0){ManualBlock(Tr("No chapter matched. Try harvest, water, drone, or unlock.","未找到章节。可尝试 harvest、浇水、无人机或解锁。"));return;}
            var exact=UnifiedManual.Functions.FirstOrDefault(f=>f.name.Equals(manualQuery,StringComparison.OrdinalIgnoreCase));if(exact!=null)manualChapter=exact.category=="product"?"world_products":exact.category=="earth"||exact.category=="builtin"?"api":"world_api";
            if(!chapters.Any(c=>c.id==manualChapter))manualChapter=chapters[0].id;
            for(int i=0;i<chapters.Length;i+=3)
            {
                var nav=Panel("Manual Chapter Navigation",modalBody,Vector2.zero,Vector2.one,Color.clear);nav.gameObject.AddComponent<UnityEngine.UI.LayoutElement>().preferredHeight=48;
                for(int col=0;col<3&&i+col<chapters.Length;col++){var c=chapters[i+col];Skin(Button(L10n.T(c.zhTitle),nav,new Vector2(col/3f+.004f,0),new Vector2((col+1)/3f-.004f,1),()=>{manualChapter=c.id;Open("guide");}),c.id==manualChapter?Accent:Dark,Color.white);}
            }
            var selected=chapters.First(c=>c.id==manualChapter);
            ManualBlock(L10n.T(selected.zhTitle));
            ManualBlock(L10n.T(selected.zh));
            if(selected.code!="")ManualBlock(selected.code,true);
            BuildFunctionReference(selected.id);
            if(selected.id=="progression")
            {
                foreach(var id in new[]{"expand","speed","grass","trees","carrots","pumpkins","sunflowers","cactus","mazes","dinosaurs","megafarm"})
                {
                    var tiers=ClassicProgression.TierDiscoveries[id];ManualBlock(TechName(id)+"\n"+string.Join("  /  ",tiers.Select((stage,i)=>(i+1)+": "+(stage==""?Tr("Base discovery","基础解锁"):TechName(stage)))));
                }
            }
            Paragraph(Tr("Use Research for live requirements, Templates for runnable examples, and Records to acknowledge completed achievements.","实时条件见科技树；可运行范例见模板；已完成成就可在纪录中查看。"),65);
        }
    }
    public static class ClassicManual
    {
        public sealed class Api {public string signature,en,zh;public Api(string s,string e,string z){signature=s;en=e;zh=z;}}
        public static readonly ManualChapter[] Chapters={
            new ManualChapter("start","01 / Enter the universe","01 / 进入宇宙","Only Earth is initially unlocked. Enter Earth, run harvest() after the first grass matures, and pay for Loops, Planting and Sensors. The original Earth crop progression is retained; Spaceflight is a later discovery. Other planets begin at one native plot when researched. This version uses a separate Universe0131 save directory so the previous live game is preserved.","初始只开放地球。进入地球，等第一格草成熟后运行harvest()，再研究循环、种植和传感器。地球保留原有作物发展路线，星际航行为后期发现；其他星球在科技解锁后各从一格开始。本版本使用独立Universe0131存档目录，保留此前游戏。","harvest()"),
            new ManualChapter("spherical","02 / Spherical coordinates","02 / 球面坐标","Earth is the original farm on a sphere, not a second garden. Expansion stages are 1×1,2×2,4×4,8×8,16×16,32×32,64×64,128×128,256×128,360×128. Each cell spans one degree. Full latitude coverage is the belt -64° to+64°, excluding both poles. Only a fully unlocked 360-column surface wraps longitude; latitude never wraps. Expansion centers the old patch, keeps plants and shifts local coordinates. Read current coordinates after expanding. Use get_world_width and get_world_height separately.","地球就是原有农场的球面版本，不是额外花园。扩展依次为1×1、2×2、4×4、8×8、16×16、32×32、64×64、128×128、256×128、360×128。每格占1°。完整纬度范围为南纬64°至北纬64°，两极不可用。只有横向360列全开才环绕，纵向从不环绕。扩展会居中保留旧地块和作物，局部坐标相应重新编号，请扩展后重读坐标。宽高分别查询。","width = get_world_width()\nheight = get_world_height()"),
            new ManualChapter("progression","03 / Research & expansion","03 / 科技与扩展","Original crop discoveries gate Earth expansion, speed and yield. The last four Earth expansion tiers need Spaceflight, Flower Planet, Mineral Planet and Ocean Planet. Buy Spaceflight after Parallel Drones, Modules, Dictionaries and Irrigation. Flower Planet costs2000 pumpkin; Ocean Planet20000 carrot; Mineral Planet5000 cactus. Exterior surfaces expand using local produce: price20×next stage squared, paid in rose,carp or stone. No elapsed-time certificate forces a wait.","地球扩张、执行速度和增产仍有原有作物发现门槛；最后四次扩张分别需要星际航行、花卉、矿物、海洋星球。星际航行需要并行无人机、模块、字典和灌溉。花卉星球消耗2000南瓜，海洋星球20000胡萝卜，矿物星球5000仙人掌。外星表层按20×下一级平方付费，以当地玫瑰、鲤鱼或石头支付。没有强制等待时长认证。","requirements = get_unlock_requirements(Unlocks.Spaceflight)"),
            new ManualChapter("crops","04 / Original Earth crops","04 / 地球原有作物","Keep original crop mechanics: tree spacing, companions, water and infection; giant pumpkin squares, dead replacements; sunflower petal priority; sorted cactus regions; connected mazes; dinosaur tails and bone settlement. Treasure produces coins, while gold is a refined mineral. Crop movement now respects spherical edges. Re-read rectangular extents and reset to the beginning after a sweep. Expanded grids preserve planted crops.","保留林木间距、伴生、水分感染、巨型南瓜与死亡替换、太阳花花瓣优先级、仙人掌排序连收、连通迷宫、长尾与骨头结算。宝藏产出coins金币，gold现在专指黄金锭。作物移动遵守球面边界，巡田须查询矩形宽高并返回起点；扩张不再清除原有作物。","if get_water() < 0.3:\n    use_item(Items.Water)"),
            new ManualChapter("language","05 / Python-inspired language","05 / 类Python语言","The game interpreter is a documented subset, not system Python. It supports loops, conditionals, functions, closures, defaults, positional arguments, collections, modules and return values. It has no OS/file/network/stdlib access, exceptions or keyword arguments. New sum/enumerate/zip/sorted/reversed/round/all/any/pow/divmod/type/Unicode helpers and string methods are documented individually. Collection operations return snapshots rather than Python lazy iterators/views. Numbers use a shared numeric representation.","游戏解释器是明确记录的Python子集，不是系统Python。支持循环、条件、函数、闭包、默认值、位置参数、集合、模块和返回值；不提供操作系统、文件、网络、标准库访问，也不支持异常捕获与关键字参数。新增sum、enumerate、zip、sorted、reversed、round、all、any、pow、divmod、type、Unicode和字符串方法，逐项见接口说明。集合操作返回快照列表，而非Python惰性迭代器或视图；数值使用统一表示。","for index, value in enumerate([10, 20], 1):\n    print(index, value)"),
            new ManualChapter("studio","06 / Program targets","06 / 程序执行目标","Top navigation opens Universe, Colony, Research, Programs, Manual, UFO, Records and Settings. Program center targets and files scroll independently. A worker, a planet manager and the universe controller each have at most one interpreter. Bind only stops and associates; Bind+run starts. Browsing another file never replaces running code. Green means running; an amber border means editing. At least one file remains. Numeric and Chinese file names are supported.","顶栏包含宇宙、殖民地、科技、程序、手册、UFO、纪录、设置。程序中心目标与文件独立滚动。每台载具、每个星球管理和宇宙总控各最多一个解释器；仅绑定会停止旧代码并关联文件，绑定运行会启动。浏览其他文件不会替换已有执行。绿色表示运行，琥珀边框表示编辑，至少保留一个文件，支持数字和中文名称。","program_bind(id, \"bee_worker\")\nprogram_run(id)"),
            new ManualChapter("workers","07 / Native craft & hulls","07 / 本地载具与机体","Earth has drones, Floralia bees, Pelagia fishing boats, Aurelia mining drones. They cannot change planets. Each planet has separate slotTier and hullTier variables; both require paid local research. Hulls1×1,2×1,2×2,3×2,3×3 occupy real cells and must fit unlocked space. Worker paths reserve full footprints and queue when blocked. Bees flap wings, drones spin rotors, boats animate propellers and mining drones animate drills.","地球是无人机，芳华是小蜜蜂，沧澜是渔船，鎏金是采矿无人机，均不能跨星球。各星球有独立slotTier数量和hullTier尺寸变量，分别付费研究。1×1、2×1、2×2、3×2、3×3占据真实格子，必须能放进已开放范围；路径检查完整占地，拥堵时等待。蜜蜂扇翅、无人机转旋翼、渔船转推进器、矿机转钻头。","worker_research(1, \"slots\")\nworker_research(1, \"size\")"),
            new ManualChapter("flowers","08 / Floralia botanical colony","08 / 芳华花卉星球","Bees manage rose,tulip,lavender,lily,orchid and lotus batches; honey is collected from rose resources. Rose works on the first plot, tulip/lavender need width2, and lily/orchid/lotus width4. Water and compost arrive by UFO. Orchids need refined silver; lotus needs fishmeal. Inputs and outputs scale with hull area, while batch time uses0.8+0.2×sqrt(area).","蜜蜂管理玫瑰、郁金香、薰衣草、百合、兰花、荷花，蜂蜜使用玫瑰花源收集。一格可种玫瑰，郁金香／薰衣草需要宽度2，百合／兰花／荷花需要宽度4。水和堆肥通过UFO送达；兰花需要白银，荷花需要鱼粉。投入和产出乘机体面积，耗时乘0.8＋0.2×sqrt(面积)。","cultivate_rose(worker_self(), 4)"),
            new ManualChapter("ocean","09 / Pelagia fisheries","09 / 沧澜海洋星球","Boats catch carp,trout,salmon,cod,tuna and koi using fish feed; koi also require lotus. Shoals are spatial: planet_scan reveals the species and a boat navigates to a matching accessible cell before processing. More species become available as the surface expands. Fishmeal processes caught carp. None of these functions creates free fish without input or time.","渔船用鱼饵捕获鲤鱼、鳟鱼、鲑鱼、鳕鱼、金枪鱼、锦鲤，锦鲤还需荷花。鱼群有空间分布，planet_scan可查种类，渔船会先前往相应已开放格再作业。扩展表层才可接触更多鱼群。鱼粉由鲤鱼加工，不存在无原料、无耗时直接赠鱼的调用。","tile = planet_scan(2, 0, 0)\ncatch_carp(worker_self(), 2)"),
            new ManualChapter("minerals","10 / Aurelia mining & refining","10 / 鎏金采矿与冶炼","Mining produces stone, copper_ore,tin_ore,silver_ore,gold_ore,platinum_ore and rough_diamond. Native drones navigate to matching deposits. Smelting produces copper,tin,bronze,silver,gold; platinum is refined and diamond is cut. Bronze consumes3 copper+1 tin+solar energy, not stone. Platinum needs roses and diamond cutting needs orchids. Deposits are renewable batch sources in this edition; energy is consumed for each mining/refining batch.","采矿产出石头、铜矿石、锡矿石、银矿石、金矿石、铂矿石和金刚石原石，采矿无人机会前往对应矿脉。冶炼产出铜锭、锡锭、青铜、白银和黄金锭；铂金需精炼，钻石需切割。青铜消耗3铜锭＋1锡锭＋太阳能，不是石头。铂金需要玫瑰，切钻需要兰花。本版矿脉为可重复批次资源，每批采矿和冶炼均支付相应能量。","mine_copper_ore(worker_self(), 2)"),
            new ManualChapter("ufo","11 / UFO freight & energy","11 / UFO货运与能源","Only UFOs move items between planets. Build costs50 credits+20wood+10solar energy on Earth and provides120 battery. Launch atomically reserves full stock and battery: ceil(amount/capacity)×(2+planet-ID distance). Each flight leg lasts12+6×planet-ID distance seconds. Capacities24,72,144,288 and1–4 ships are researched independently using returned bronze/silver/platinum. Refuel at the current dock with local solar energy:5 battery/unit, maximum1000. Cancel refunds unused stock immediately; airborne cargo finishes its current leg and deposits at destination.","只有UFO能跨星球转移物资。地球建造需50资金＋20木材＋10太阳能，初始120电量。发射同时预留整批库存与电量：ceil(数量/载荷)×(2＋星球编号距离)。每航段耗时12＋6×编号距离秒。载荷24／72／144／288与数量1～4分别用回运青铜、白银、铂金研究。只能用当前停靠星球的太阳能充电，每份补5，上限1000。取消立即退回未装载库存；在途货物安全完成当前航段并存入目的地。","ship = ufo_build()\nif ship > 0:\n    ufo_transfer(ship, 0, 1, \"water\", 24)"),
            new ManualChapter("swarm","12 / Local swarms & messages","12 / 本地集群与消息","swarm_create names unique worker IDs from one planet. Several groups may coexist, and one file can run as independent copies. Variables and module instances are isolated; messages are deep-copied and inboxes hold16 values. fleet_receive is nonblocking and returns None when empty. Use separate planet managers and a universe program to coordinate different swarms.","swarm_create为同一星球的不同载具编号建立命名集群，可有多个集群；同一文件可作为多个独立副本运行。变量和模块状态隔离，消息深拷贝，收件箱最多16条；fleet_receive非阻塞，空时None。跨星球协作由各星球管理和宇宙总控安排。","swarm_create(\"bee_team\", [a, b])\nswarm_run(\"bee_team\", \"bee_worker\")"),
            new ManualChapter("patterns","13 / Controller hierarchy","13 / 总控与子程序调用","Create the 11-file universe example. Run universe_controller on Universe; it launches managers for unlocked planets. Each manager binds its native starter worker. Parent completion does not stop children. Managers do not consume worker slots. Worker errors stop only that interpreter. Physical work queues may continue after code stops; use worker_cancel or stop_all deliberately.","创建11文件宇宙范例，将universe_controller绑定到宇宙。它为已解锁星球启动管理，各管理绑定本地初始载具。父程序结束不停止子程序，管理程序不占载具名额。单机报错只停自身；代码停止后实体队列仍可能继续，需明确调用worker_cancel或stop_all。","planet_run(1, \"flower_manager\")\nplanet_run(2, \"ocean_manager\")"),
                        new ManualChapter("orbital","18 / Mothership, landing & freight","18 / 母舰、降落与轨道物流","Locked worlds appear grey, each rotating on its own randomized axis. Select an unlocked planet to watch the shuttle descend from the mothership. Native workers stay local. Every interplanetary UFO route passes through the mother; use depot -1 to store and retrieve supplies. Cancellation deposits airborne cargo at its next dock, which may be the mother. Local solar energy is required to refuel.","未解锁星球显示为灰色，各星球沿随机独立轴旋转。选择已开放星球，穿梭机从母舰降落。本地载具不会跨星球，所有跨星UFO航线经过母舰。仓库编号−1用于存入与提取母舰物资。取消任务时，在途货物停靠当前航段目标，可能进入母舰；补能必须使用当前泊位太阳能。","ufo_transfer(ship, 0, -1, 'water', 24)\nufo_wait(ship)\nprint(mothership_inventory('water'))"),
                        new ManualChapter("native_science","19 / Native research, growth & effects","19 / 专属科技、生长与特效","Research has Universe, Earth, Flower, Ocean and Mineral sectors. Planet discovery is in Universe. Green is production, blue automation, amber ecology, violet transport. Dark nodes are unresearched; bright nodes have a purchased level. Native research changes real recipe speed/yields; costs double per level, five levels per branch. Growth now changes crop shape continuously. A close-up is selected for small fields; harvest bursts use a bounded shared pool. Full-size surfaces cull distant/back-facing crop chunks and batch the visible instances. There is no fixed campaign timer gate.","科技分为宇宙、地球、花卉、海洋和矿物分区，星球解锁位于宇宙分区。绿色生产、蓝色自动化、橙色生态、紫色运输；暗色未研究，亮色已购买。专属科技真实改变配方耗时或产量，每项五级，费用逐级翻倍。作物形态连续生长，小农场默认近景；收获特效使用有数量上限的共享池。大地图筛选背面和远处作物块，并批量绘制可见实例。流程不设置固定等待时间门槛。","nodes = planet_technologies(1)\nplanet_research(1, 'pollination')"),
            new ManualChapter("save","14 / Saves, compatibility & debugging","14 / 存档、兼容与调试","0.13.2 saves are isolated under Automation/Universe0131. Old farm files are retained and not silently converted into a different universe. Save physical cargo, queues, battery, surfaces, swarms and file bindings. Interpreter stacks,inboxes and result objects are transient; restart controllers after loading and inspect existing queues. Original race farms remain separate. Ctrl/Cmd+Z undo, Shift+Ctrl/Cmd+Z redo, F9 breakpoints and external editing remain.","0.13.2存档隔离在Automation/Universe0131，旧农场保留，不会静默转换成另一套宇宙。保存实体货物、队列、电量、表层、集群和绑定文件；调用栈、收件箱和结果不保存。读档后检查已有队列再重启总控。本地竞速仍是独立预设。保留撤销重做、F9断点和外部编辑器。","state = worker_state(id)"),
            new ManualChapter("api","15 / Earth & Python reference","15 / 地球与Python函数全集","Every retained Earth function and Python-inspired helper has an individual entry below, including defaults, results and examples. Keys are case-sensitive. No keyword arguments. get_world_size is a compatibility width query, not a rectangular height.","以下逐项介绍原有地球函数与类Python工具，包括默认参数、返回值和示例。名称区分大小写，不支持关键字参数。get_world_size只是兼容宽度查询，不代表矩形高度。",""),
            new ManualChapter("world_api","16 / Universe, workers & UFO API","16 / 宇宙、载具与UFO函数全集","Use universe_ for global management, planet_ for a colony, worker_ for native craft, swarm_ for local groups and ufo_ exclusively for interplanetary freight. Kept fleet_/island_ names are compatibility spellings and are documented separately. fleet_ship and fleet_rebase are retired, not teleport shortcuts.","universe_用于宇宙管理，planet_用于星球，worker_用于本地载具，swarm_用于本地集群，ufo_专用于星际货运。保留的fleet_／island_仅为兼容名称，单独标记说明。fleet_ship与fleet_rebase已移除，不是瞬移捷径。",""),
            new ManualChapter("world_products","17 / Every production function","17 / 全部产物专属函数","Each product function maps to exactly one native recipe. It enqueues work, never an immediate free item. The recipe table below is exported from the runtime. Distinguish coins, gold_ore and gold; raw minerals and refined products are separate inventory IDs.","每个专属函数精确对应一份本地配方，调用只排队，不会立即免费发放物资。下方配方来自实际运行数据。coins金币、gold_ore金矿石、gold黄金锭严格区分，原矿和成品使用不同库存编号。","")};
        public static readonly Api[] Apis=UnifiedManual.Functions.Select(f=>new Api(f.signature,f.en,f.zh)).ToArray();
    }
}
